107	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
108	        HttpHeaders headers = new HttpHeaders();
109	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
110	        this.clinicService.saveOwner(owner);
111	        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
112	        String user = (authentication != null) ? authentication.getName() : "anonymous";
113	        auditLogger.info("Owner created by user={} id={} membershipNumber={}",
114	            user, owner.getId(), owner.getMembershipNumber());
115	        warnIfPossibleBulkSignup(owner);
116	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
117	        headers.setLocation(UriComponentsBuilder.newInstance()
118	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
119	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
120	    }
