122	    /**
123	     * The number of existing owners that must already share a newly created owner's area
124	     * code (the first three digits of the telephone) before a possible bulk signup is flagged.
125	     */
126	    private static final long BULK_SIGNUP_AREA_CODE_THRESHOLD = 5;
127	
128	    /**
129	     * Emits a WARN to the AUDIT logger when the newly created {@code owner}'s telephone area
130	     * code (its first three digits) is already shared by {@link #BULK_SIGNUP_AREA_CODE_THRESHOLD}
131	     * or more existing owners, flagging a possible bulk signup. The newly created owner is
132	     * excluded from the count.
133	     */
134	    private void warnIfPossibleBulkSignup(Owner owner) {
135	        String areaCode = areaCode(owner.getTelephone());
136	        if (areaCode == null) {
137	            return;
138	        }
139	        long sharing = this.clinicService.findAllOwners().stream()
140	            .filter(existing -> !java.util.Objects.equals(existing.getId(), owner.getId()))
141	            .filter(existing -> areaCode.equals(areaCode(existing.getTelephone())))
142	            .count();
143	        if (sharing >= BULK_SIGNUP_AREA_CODE_THRESHOLD) {
144	            auditLogger.warn("Possible bulk signup: area code {} shared by {} existing owners; new owner id={}",
145	                areaCode, sharing, owner.getId());
146	        }
147	    }
148	
149	    /**
150	     * Returns the area code of a telephone number, i.e. the first three digits after stripping
151	     * any non-digit characters, or {@code null} if the number is {@code null} or has fewer than
152	     * three digits.
153	     */
154	    private static String areaCode(String telephone) {
155	        if (telephone == null) {
156	            return null;
157	        }
158	        String digits = telephone.replaceAll("[^0-9]", "");
159	        return digits.length() >= 3 ? digits.substring(0, 3) : null;
160	    }
